// Pull the LLM's text field (Claude/GPT)
const txt =
  $json?.content?.[0]?.text ??
  $json?.choices?.[0]?.message?.content ??
  "";

// 1) Strip code fences or stray wrappers, isolate the JSON array
let cleaned = String(txt).trim();

// Some models wrap in markdown fences
cleaned = cleaned.replace(/^```json\s*/i, "").replace(/\s*```$/i, "").trim();

// Some tools wrap the array with parentheses or extra text; try a direct parse first
let arr;
try {
  arr = JSON.parse(cleaned);
} catch {
  const m = cleaned.match(/\[[\s\S]*\]/); // extract the first JSON array
  if (!m) throw new Error("LLM output doesn't contain a JSON array. First 300 chars: " + cleaned.slice(0,300));
  arr = JSON.parse(m[0]);
}
if (!Array.isArray(arr)) throw new Error("Parsed payload is not an array");

// --- helpers ---
const clamp100 = (v) => {
  const n = Number(v);
  if (v === null || v === undefined || v === "" || !isFinite(n) || n < 0 || n > 100) return null;
  return Math.max(0, Math.min(100, Number(n.toFixed(1))));
};
const pos = (v) => {
  const n = Number(v);
  if (v === null || v === undefined || v === "" || !isFinite(n) || n < 0) return null;
  return Number(n.toFixed(1));
};

// Normalize ICD object: allow null code/version but always keep description
function normICD(obj) {
  if (!obj || typeof obj !== "object") {
    return { code: null, version: null, description: "" };
  }
  let { code = null, version = null, description = "" } = obj;

  // Normalize code text (uppercase, trim); keep dots if provided
  if (code != null) {
    code = String(code).trim().toUpperCase();
    if (code === "" || code === "NULL") code = null;
  }

  // version should be 9 or 10 if present
  if (version != null) {
    const v = Number(version);
    version = (v === 9 || v === 10) ? v : null;
  }

  description = String(description ?? "").trim();

  return { code, version, description };
}

// Some models might send days instead of hours; detect from key name or value size
function pickExpectedHours(p) { return p.expected_los_hours == null ? null : pos(p.expected_los_hours); }

const out = arr.map((p, i) => {
  // case_id can be anything; keep as string
  const case_id = String(p.case_id ?? `case_${i}`);

  // Primary diagnosis (object)
  const primary_diagnosis = normICD(p.primary_diagnosis);

  // Secondary diagnoses (array of objects)
  const secondary_diagnoses = Array.isArray(p.secondary_diagnoses)
    ? p.secondary_diagnoses.map(normICD)
    : [];

  // Risks: clamp to [0,100], 1 decimal, no % sign
  const in_hosp = clamp100(p.in_hospital_mortality_risk_pct);
  const mort30  = clamp100(p.mort30_risk_pct);
  const readm30 = clamp100(p.readmit30_risk_pct);

  // LOS in hours
  const expected_los_hours = pickExpectedHours(p);

  // Interventions / safety
  const key_interventions = Array.isArray(p.key_interventions) ? p.key_interventions.map(x => String(x)) : [];
  const safety_flags      = Array.isArray(p.safety_flags) ? p.safety_flags.map(x => String(x)) : [];

  // Rationale (trim length)
  let rationale = String(p.rationale ?? "").trim();
  if (rationale.length > 900) rationale = rationale.slice(0, 900);

  return {
    json: {
      case_id,
      primary_diagnosis,
      secondary_diagnoses,
      in_hospital_mortality_risk_pct: in_hosp,
      mort30_risk_pct: mort30,
      readmit30_risk_pct: readm30,
      expected_los_hours,
      key_interventions,
      safety_flags,
      rationale,
    }
  };
});

return out;

const VERSION="mas_original_severity_v3";
const TARGETS=["in_hospital_mortality","mortality_30d","readmission_30d","los_days"];
function parseJsonTransport(raw){
