   if(quoted&&code<32){if(escaped)throw original;out+='\\u'+code.toString(16).padStart(4,'0');positions.push(i);continue;}
   out+=ch;
   if(escaped){escaped=false;continue;}
   if(quoted&&ch==='\\'){escaped=true;continue;}
   if(ch==='"')quoted=!quoted;
