 for(const f of a.severity_assessment?.findings??[])if(f.direction==='reassuring'){f.direction='decreases';note('findings.'+f.id+'.direction','Equivalent reassuring label normalized to decreases');}
 const findings=a.severity_assessment?.findings??[];
 for(const t of TARGETS){
  const relevant=findings.filter(f=>Array.isArray(f.targets)&&f.targets.includes(t)).map(f=>f.id),risk=a.severity_assessment?.risk_by_endpoint?.[t],fit=a.cohort_fit?.[t];
  if(risk&&Array.isArray(risk.finding_ids)){const filtered=risk.finding_ids.filter(id=>relevant.includes(id));if(filtered.length!==risk.finding_ids.length){risk.finding_ids=filtered;note('risk_by_endpoint.'+t,'Off-endpoint references removed; original findings retained for their recorded endpoints');}}
