   const captured=[],unmatched=[],unknown=[],seen=new Set();
   for(const c of fit.captured){if(!c||!relevant.includes(c.finding_id)){note('cohort_fit.'+t,'Off-endpoint capture ignored');continue;}if(seen.has(c.finding_id))continue;seen.add(c.finding_id);
