   for(const id of relevant)if(!seen.has(id)){unknown.push(id);note('cohort_fit.'+t+'.'+id,'Omitted fit classification recorded as unknown, not matched');}
   if(captured.length!==fit.captured.length&&fit.status==='adequate'){fit.status='limited';note('cohort_fit.'+t+'.status','Capture removed; adequacy downgraded');}
   fit.captured=captured;fit.unmatched=unmatched;fit.unknown=unknown;
  }
  const d=a.numeric_decisions?.[t];if(d&&['retain','combine','abstain'].includes(d.action)&&d.adjustment===0){d.adjustment=null;note('numeric_decisions.'+t+'.adjustment','Explicit zero converted to canonical no-adjustment null');}
  const p=a.predictions?.[t];if(p&&['from_source','retained_from_source'].includes(p.status)&&d?.action==='retain'){p.status='estimated';note('predictions.'+t+'.status','Explicit retained-source status normalized to estimated; source/arithmetic validation still required');}
 }
