function resolveMedications(c){
 const candidates=[['role_views.pharmacy.meds_admin',c.role_views?.pharmacy?.meds_admin],['narrative_sop.meds_admin',c.narrative_sop?.meds_admin]];
 const inspected=[];
 for(const [source,raw] of candidates){
  let list=raw;
  if(typeof list==='string'){const s=list.trim();if(s.startsWith('[')||s.startsWith('{')){try{list=JSON.parse(s);}catch{list=[];}}else list=s?s.split(/[\n;]+/):[];}
  if(list&&typeof list==='object'&&!Array.isArray(list))list=[list];
  if(!Array.isArray(list))list=[];
  const entries=[];let rejected=0;
  for(const m of list){const name=typeof m==='string'?m:[m?.drug,m?.name,m?.medication_name,m?.medication].find(x=>typeof x==='string'&&x.trim());
