  f={...root.demographics_features};
  const history=c.patient_context?.history_icd10;
  const s=Array.isArray(history)?history.map(x=>x.description??'').join(' ').toLowerCase():'';
  const patterns={has_chf:/heart failure|congestive failure/,has_diabetes:/diabet/,has_copd:/chronic obstructive|\bcopd\b/,has_ckd:/chronic kidney|chronic renal|\bckd\b|end.stage renal/,has_cancer:/malignan|carcinoma|neoplasm|\bcancer\b/,has_immunosupp:/immunosuppress|immunodeficien|\bhiv\b/,has_neutropenia:/neutropeni/,has_pneumonia:/pneumonia/,has_cvc_inf:/infection.*(?:central venous|vascular catheter)|(?:central venous|vascular catheter).*infection/};
