  const required={has_sepsis:['lactate','wbc'],has_aki:['creatinine','bun'],has_liver_dysfunction:['bilirubin','ast','alkphos'],has_coagulopathy:['inr','platelets'],has_malnutrition:['albumin','hemoglobin'],has_metabolic_acidosis:['bicarbonate','lactate']};
  for(const[k,needs]of Object.entries(required))if(needs.some(k=>v[k]===null))f[k]=null;
