  for(const k of Object.keys(f))if(f[k]===false)f[k]=null;
 }
 const known=Object.keys(f).filter(k=>f[k]!==null&&f[k]!==undefined&&!['min_matches','age_tolerance','score_tolerance','observed_analytes'].includes(k));
 return {case_id:id,hadm_id:Number(match[1]),role,version:VERSION,patient_evidence:evidence,matching_features:f,matching_audit:{matched_feature_keys:known,omitted_unknown_features:missing,limitations:['Legacy cohort source features have unverified timing and coverage.','Lexical patterns are not validated clinical diagnoses.','Unknown conditions are not filtered as documented negatives.','Same-patient admissions excluded; no cross-patient temporal isolation is claimed.',...(role==='laboratory'?['Partial lab scores may not be comparable with complete-panel source scores.']:[])]}};
