 if(c.probability_unit!=='fraction'||c.los_unit!=='days'||c.los_statistic!=='mean'||c.mortality_30d_origin!=='discharge'||c.cohort_unit!=='admissions'||c.same_patient_excluded!==true)throw Error('SQL unit/endpoint/provenance contract mismatch');
