// This Function expects one item carrying the raw ChatGPT completion JSON.
// It outputs one item per predicted case, normalized to our evaluation schema.

// 1) Get the OpenAI completion payload
const root = items[0]?.json;
if (!root) throw new Error("Missing completion payload in items[0].json");

// 2) Extract the array of predictions from ChatGPT
  let arr;

  // OpenAI v1 style
  let content = root?.choices?.[0]?.message?.content;

  // Rare wrapper: root is array
  if (!content && Array.isArray(root) && root[0]?.choices?.[0]?.message?.content) {
    content = root[0].choices[0].message.content;
  }

  const pickArrayFromObject = (obj) => {
    if (!obj || typeof obj !== "object") return null;
    if (Array.isArray(obj)) return obj;

    const preferredKeys = ["items", "predictions", "results", "data", "output", "cases"];
    for (const k of preferredKeys) {
      if (Array.isArray(obj[k])) return obj[k];
    }

    for (const v of Object.values(obj)) {
      if (Array.isArray(v)) return v;
    }
    return null;
  };

  const parseJsonMaybe = (s) => {
    const cleaned = String(s ?? "").trim()
      .replace(/^```json\s*/i, "")
      .replace(/^\s*```/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    try {
      return JSON.parse(cleaned);
    } catch {
      const m = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
      if (!m) return null;
      return JSON.parse(m[1]);
    }
  };

  if (typeof content === "string") {
    const parsed = parseJsonMaybe(content);
    arr = pickArrayFromObject(parsed);
  } else if (Array.isArray(content)) {
    if (content.length && typeof content[0] === "object" && content[0]?.text) {
      const joined = content.map(c => c?.text ?? "").join("\n");
      const parsed = parseJsonMaybe(joined);
      arr = pickArrayFromObject(parsed);
    } else {
      arr = content;
    }
  } else if (content && typeof content === "object") {
    arr = pickArrayFromObject(content);
  }

  if (!Array.isArray(arr) || arr.length === 0) {
    const keys = content && typeof content === "object" ? Object.keys(content).join(", ") : "";
    throw new Error(`Unsupported/empty prediction payload. contentType=${typeof content}, keys=[${keys}]`);
  }

// --- Helpers ---
const clamp100 = (v) => {
  const n = Number(v);
  if (v === null || v === undefined || v === "" || !isFinite(n) || n < 0 || n > 100) return null;
  return Math.max(0, Math.min(100, Number(n.toFixed(1))));
};

const pos = (v) => {
  const n = Number(v);
  if (v === null || v === undefined || v === "" || !isFinite(n) || n < 0) return null;
  return Number(n.toFixed(1));
};

// Normalize ICD: allow null code/version; always return description (string)
function normICD(obj) {
  if (!obj || typeof obj !== "object") {
    return { code: null, version: null, description: "" };
  }
  let { code = null, version = null, description = "" } = obj;

  if (code != null) {
    code = String(code).trim().toUpperCase();
    if (code === "" || code === "NULL") code = null;
  }

  if (version != null) {
    const v = Number(version);
    version = (v === 9 || v === 10) ? v : null;
  }

  description = String(description ?? "").trim();
  return { code, version, description };
}

// Some models may return days; convert to hours if needed
function pickExpectedHours(p) { return p.expected_los_hours == null ? null : pos(p.expected_los_hours); }

const out = arr.map((p, i) => {
  const case_id = String(p.case_id ?? `case_${i}`);

  const primary_diagnosis = normICD(p.primary_diagnosis);
  const secondary_diagnoses = Array.isArray(p.secondary_diagnoses)
    ? p.secondary_diagnoses.map(normICD)
    : [];

  const in_hosp = clamp100(p.in_hospital_mortality_risk_pct);
  const mort30  = clamp100(p.mort30_risk_pct);
  const readm30 = clamp100(p.readmit30_risk_pct);

  const expected_los_hours = pickExpectedHours(p);

  const key_interventions = Array.isArray(p.key_interventions)
    ? p.key_interventions.map(x => String(x))
    : [];
  const safety_flags = Array.isArray(p.safety_flags)
    ? p.safety_flags.map(x => String(x))
    : [];

  let rationale = String(p.rationale ?? "").trim();
  if (rationale.length > 900) rationale = rationale.slice(0, 900);

  return {
    json: {
      case_id,
      primary_diagnosis,
      secondary_diagnoses,
      in_hospital_mortality_risk_pct: in_hosp,
      mort30_risk_pct: mort30,
      readmit30_risk_pct: readm30,
      expected_los_hours,
      key_interventions,
      safety_flags,
      rationale
