// Expecting input in $json.case_string, e.g. "mimic-3p1-CASE_EXAMPLE"
const input = $input.first().json.scenario_id;
const m = input.match(/CASE_(\d+)/i);
if (!m) {
  throw new Error(`Couldn't find CASE_<digits> in: ${input}`);
}

// Enforce an integer to keep things safe
const case_id = Number.parseInt(m[1], 10);
if (!Number.isInteger(case_id)) {
  throw new Error(`Extracted case_id is not an integer: ${m[1]}`);
}

// Output { case_id: 25849114 }
return [{ case_id }];

// Copy all existing fields
const item = { ...$json };

// If case_id is an integer, add the prefix
if (typeof item.case_id === 'number' || /^\d+$/.test(item.case_id)) {
  item.case_id = `mimic-3p1-CASE_${item.case_id}`;
}

return [item];

