  // alter numbers/keys, remove fields, or repair unquoted syntax/invalid escapes.
  return {value:JSON.parse(out),repairs:[{path:'json_transport',reason:'Literal in-string control characters encoded as JSON Unicode escapes; semantic content unchanged',positions}]};
 }
}
