    if (picked.length >= Math.min(10, maxTotal)) break;
    if (key.test(d?.description ?? "")) pushUnique(d);
  }
  for (const d of sorted) {
    if (picked.length >= maxTotal) break;
    pushUnique(d);
  }
  return picked;
